#!/usr/bin/env python3
"""Galaxy-side diagnostic for the 1000G/AFGR identity and BAM selection."""

import json
import sys
from collections import defaultdict


def fail(message):
    raise SystemExit(message)


def experiment_id(path):
    parts = [part for part in str(path).split("/") if part]
    return parts[-1] if parts else ""


def normalized_sample_name(sample):
    """Map the Coriell GM alias used by ENCODE to the 1000G NA identifier."""
    if isinstance(sample, str) and sample.startswith("GM") and sample[2:].isdigit():
        return "NA" + sample[2:]
    return sample


